<?php include "db.php"; if(!isset($_SESSION['user_id'])){header("Location: login.php");exit();} $uid=(int)$_SESSION['user_id'];if(isset($_GET['cancel'])){$id=(int)$_GET['cancel'];$stmt=mysqli_prepare($conn,"SELECT checkin,status FROM bookings WHERE id=? AND user_id=?");mysqli_stmt_bind_param($stmt,"ii",$id,$uid);mysqli_stmt_execute($stmt);$b=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if($b&&$b['status']==='Booked'&&strtotime($b['checkin'])>=strtotime('+3 days')){$stmt=mysqli_prepare($conn,"UPDATE bookings SET status='Cancelled' WHERE id=? AND user_id=?");mysqli_stmt_bind_param($stmt,"ii",$id,$uid);mysqli_stmt_execute($stmt);}header("Location: my_bookings.php");exit();}$stmt=mysqli_prepare($conn,"SELECT bookings.*,rooms.room_type FROM bookings JOIN rooms ON bookings.room_id=rooms.id WHERE bookings.user_id=? ORDER BY bookings.id DESC");mysqli_stmt_bind_param($stmt,"i",$uid);mysqli_stmt_execute($stmt);$rows=mysqli_stmt_get_result($stmt); ?>
<!DOCTYPE html><html><head><title>My Bookings</title><link rel="stylesheet" href="style.css"></head><body><header><h1>StayEase Hotels</h1><nav><a href="index.php">Home</a><a href="rooms.php">Rooms</a><a href="dashboard.php">Dashboard</a><a href="logout.php">Logout</a></nav></header><div class="container"><h2>My Booking History</h2><?php if(isset($_GET['success']))echo '<p class="message">Booking confirmed successfully.</p>'; ?><table><tr><th>ID</th><th>Room</th><th>Check-in</th><th>Check-out</th><th>Guests</th><th>Total</th><th>Status</th><th>Action</th></tr><?php while($b=mysqli_fetch_assoc($rows)){ ?><tr><td><?php echo $b['id']; ?></td><td><?php echo htmlspecialchars($b['room_type']); ?></td><td><?php echo $b['checkin']; ?></td><td><?php echo $b['checkout']; ?></td><td><?php echo $b['guests']; ?></td><td>₹<?php echo number_format($b['total_price'],2); ?></td><td><?php echo htmlspecialchars($b['status']); ?></td><td><?php if($b['status']==='Booked'&&strtotime($b['checkin'])>=strtotime('+3 days'))echo '<a href="my_bookings.php?cancel='.$b['id'].'" onclick="return confirm(\'Cancel this booking?\')">Cancel</a>';else echo '-'; ?></td></tr><?php } ?></table><p><small>Guest cancellation is available at least 3 days before check-in.</small></p></div></body></html>